import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Multi-page forms","description":"Split long forms across several pages.","frontmatter":{"title":"Multi-page forms","description":"Split long forms across several pages."},"headers":[],"relativePath":"en/formulare/mehrseitige-formulare.md","filePath":"en/formulare/mehrseitige-formulare.md","lastUpdated":1787319236000}'),i={name:"en/formulare/mehrseitige-formulare.md"};function n(s,e,l,d,p,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="multi-page-forms" tabindex="-1">Multi-page forms <a class="header-anchor" href="#multi-page-forms" aria-label="Permalink to &quot;Multi-page forms&quot;">​</a></h1><p>A form can consist of several <strong>form pages</strong>. People filling it out work through them one after another.</p><div class="tip custom-block"><p class="custom-block-title">Don&#39;t confuse this with Portal pages</p><p>A <em>form page</em> is a section within a form. It has nothing to do with a <a href="/en/seiten/was-sind-seiten">Page</a> in the Portal sense, even though both are called &quot;page.&quot;</p></div><h2 id="adding-a-page" tabindex="-1">Adding a page <a class="header-anchor" href="#adding-a-page" aria-label="Permalink to &quot;Adding a page&quot;">​</a></h2><p>In the <strong>Pages</strong> tab of the form editor: <strong>Add page to form</strong>.</p><p>Each page gets its own fields and text blocks. Use <strong>Remove page</strong> to delete one again.</p><div class="warning custom-block"><p class="custom-block-title">Fields don&#39;t move automatically</p><p>When you remove a page, the fields on it also disappear from the form. The data on the Grid stays untouched — but those fields are no longer collected.</p></div><h2 id="what-people-filling-it-out-see" tabindex="-1">What people filling it out see <a class="header-anchor" href="#what-people-filling-it-out-see" aria-label="Permalink to &quot;What people filling it out see&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Label</th></tr></thead><tbody><tr><td>Go to next page</td><td><strong>Next</strong></td></tr><tr><td>Go to previous page</td><td><strong>Back</strong></td></tr><tr><td>On the last page</td><td><strong>Submit</strong></td></tr></tbody></table><p>Submission only happens <strong>at the end</strong>. Until then, the input isn&#39;t on the Grid.</p><div class="warning custom-block"><p class="custom-block-title">Without &quot;Save to continue later,&quot; input is lost</p><p>If someone closes the form on page 3 of 5, it&#39;s all gone. For longer forms you should therefore turn on <em>Save to continue later</em>.</p><p>→ <a href="/en/formulare/speichern-und-fortsetzen">Save and continue later</a></p></div><h2 id="when-multiple-pages-pay-off" tabindex="-1">When multiple pages pay off <a class="header-anchor" href="#when-multiple-pages-pay-off" aria-label="Permalink to &quot;When multiple pages pay off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Recommendation</th></tr></thead><tbody><tr><td>Up to about 10 fields</td><td>One page, structured with heading text blocks</td></tr><tr><td>More than 10 fields</td><td>Multiple pages</td></tr><tr><td>Topically distinct sections</td><td>Multiple pages, one per topic</td></tr><tr><td>Form for mobile devices</td><td>Rather several short pages</td></tr><tr><td>Auto-submit enabled</td><td>One page — multiple pages make no sense</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Split by topic, not by field count</p><p>Good splits are content-based: &quot;Your contact details,&quot; &quot;Your request,&quot; &quot;Attachments.&quot; Bad splits separate things that belong together — for example street on page 1 and postal code on page 2.</p><p>A heading text block at the top of each page tells people where they are.</p></div><div class="tip custom-block"><p class="custom-block-title">Required fields near the front</p><p>Whatever you absolutely need belongs on the first pages. If someone abandons the form, you won&#39;t have an entry — but with saving enabled you&#39;ll at least have the important information for a follow-up.</p></div><h2 id="interaction-with-other-settings" tabindex="-1">Interaction with other settings <a class="header-anchor" href="#interaction-with-other-settings" aria-label="Permalink to &quot;Interaction with other settings&quot;">​</a></h2><p>The form builder has no <strong>conditional display</strong> per field. If you want fields to show or hide depending on an input, you need a <a href="/en/seiten/was-sind-seiten">Page</a> with <a href="/en/seiten/sichtbarkeit">conditional visibility</a> instead of a form.</p><p><strong>Multilingual support</strong> applies across all form pages. → <a href="/en/formulare/mehrsprachig">Multilingual forms</a></p><p><strong>Embedded forms</strong> with multiple pages need <em>Auto-adjust height</em>, otherwise a scrollbar appears inside the frame. → <a href="/en/formulare/formular-teilen">Sharing a form</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/formulare/formular-erstellen">Creating a form</a></li><li><a href="/en/formulare/speichern-und-fortsetzen">Save and continue later</a></li><li><a href="/en/formulare/felder-konfigurieren">Configuring fields</a></li></ul>',21)])])}const f=t(i,[["render",n]]);export{g as __pageData,f as default};
